136	    /**
137	     * 按事件与 actionKey 查询处置记录，用于幂等比对。
138	     */
139	    public Optional<IncidentAction> findAction(long incidentId, String actionKey) {
140	        List<IncidentAction> rows = jdbc.query(
141	                "SELECT * FROM incident_actions WHERE incident_id = ? AND action_key = ?",
142	                ACTION_MAPPER, incidentId, actionKey);
143	        return rows.stream().findFirst();
144	    }
145	
146	    /**
147	     * 查询事件全部处置记录，按落库顺序返回。
148	     */
149	    public List<IncidentAction> listActions(long incidentId) {
150	        return jdbc.query("SELECT * FROM incident_actions WHERE incident_id = ? ORDER BY id",
151	                ACTION_MAPPER, incidentId);
152	    }
153	
154	    /**
155	     * 创建交接单（PENDING），返回生成主键。
156	     */
157	    public long insertTransfer(IncidentTransfer transfer) {
158	        KeyHolder keys = new GeneratedKeyHolder();
159	        jdbc.update(con -> {
160	            var ps = con.prepareStatement(
161	                    "INSERT INTO incident_transfers (incident_id, from_commander, to_commander, status,"
162	                            + " created_at, accepted_at) VALUES (?,?,?,?,?,?)",
163	                    Statement.RETURN_GENERATED_KEYS);
164	            ps.setLong(1, transfer.incidentId());
165	            ps.setString(2, transfer.fromCommander());
166	            ps.setString(3, transfer.toCommander());
167	            ps.setString(4, transfer.status().name());
168	            ps.setTimestamp(5, Timestamp.from(transfer.createdAt()));
169	            ps.setTimestamp(6, transfer.acceptedAt() == null ? null : Timestamp.from(transfer.acceptedAt()));
170	            return ps;
171	        }, keys);
172	        return keys.getKey().longValue();
173	    }
174	
175	    /**
176	     * 查询事件当前待接受的交接单。
177	     */
178	    public Optional<IncidentTransfer> findPendingTransfer(long incidentId) {
179	        List<IncidentTransfer> rows = jdbc.query(
180	                "SELECT * FROM incident_transfers WHERE incident_id = ? AND status = 'PENDING'",
181	                TRANSFER_MAPPER, incidentId);
182	        return rows.stream().findFirst();
183	    }
184	
185	    /**
186	     * 将交接单标记为已接受。
187	     */
188	    public void acceptTransfer(long transferId, Instant acceptedAt) {
189	        jdbc.update("UPDATE incident_transfers SET status = 'ACCEPTED', accepted_at = ? WHERE id = ?",
190	                Timestamp.from(acceptedAt), transferId);
191	    }
192	
193	    /**
194	     * 查询事件全部交接单，按发起顺序返回。
195	     */
196	    public List<IncidentTransfer> listTransfers(long incidentId) {
197	        return jdbc.query("SELECT * FROM incident_transfers WHERE incident_id = ? ORDER BY id",
198	                TRANSFER_MAPPER, incidentId);
199	    }
200	
201	    /**
202	     * 追加状态流转历史。
203	     */
204	    public void insertStatusChange(StatusChange change) {
205	        jdbc.update("INSERT INTO incident_status_history (incident_id, from_status, to_status, actor,"
206	                        + " occurred_at) VALUES (?,?,?,?,?)",
207	                change.incidentId(),
208	                change.fromStatus() == null ? null : change.fromStatus().name(),
209	                change.toStatus().name(), change.actor(), Timestamp.from(change.occurredAt()));
210	    }
211	
212	    /**
213	     * 查询事件全部状态流转历史，按发生顺序返回。
214	     */
215	    public List<StatusChange> listStatusHistory(long incidentId) {
216	        return jdbc.query("SELECT * FROM incident_status_history WHERE incident_id = ? ORDER BY id",
217	                STATUS_MAPPER, incidentId);
218	    }
219	
220	    /**
221	     * 查询任务的全部阻塞事件（含当前状态），按事件键排序返回。
222	     * 阻塞解除不写回依赖任务，查询时按目标事件当前状态计算。
223	     */
224	    public List<Incident> listBlockingIncidents(long taskId) {
