package com.example.starter.incident;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

/**
 * 测试用可控时钟：默认指向构造时的 UTC 时刻，可通过 setInstant 推进/回退，
 * 供期限、触发与确认时刻相关测试使用。以 @Primary 覆盖生产 ClockConfig 的系统时钟。
 */
public class ControllableClock extends Clock {

    private Instant current;

    public ControllableClock(Instant initial) {
        this.current = initial;
    }

    public void setInstant(Instant instant) {
        this.current = instant;
    }

    public void advanceSeconds(long seconds) {
        this.current = current.plusSeconds(seconds);
    }

    @Override
    public ZoneId getZone() {
        return ZoneOffset.UTC;
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return Clock.fixed(current, zone);
    }

    @Override
    public Instant instant() {
        return current;
    }

    /**
     * 提供可控 Clock Bean 的测试配置。
     */
    @TestConfiguration
    public static class Config {

        @Bean
        @Primary
        public Clock controllableClock() {
            return new ControllableClock(Instant.parse("2026-09-22T00:00:00Z"));
        }
    }
}

package com.example.starter.incident;

/**
 * 处置任务状态机：OPEN → DONE 或 OPEN → CANCELLED。
 * DONE 与 CANCELLED 均为终态，不允许任何后续流转；取消仅适用于 OPEN。
 */
public enum TaskStatus {

    /** 待处理。 */
    OPEN,

    /** 已完成（要求全部阻塞事件已进入 CONTAINED/RESOLVED/CLOSED）。 */
    DONE,

    /** 已取消。 */
    CANCELLED;
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 命令幂等键实体，对应 command_keys 表。
 * requestHash 为请求规范化参数的摘要；responseBody 为首次成功响应的 JSON，
 * 用于同键同参重放；responseStatus/responseBody 在事务提交前必定写入。
 */
public record CommandKeyRecord(
        long id,
        String commandKey,
        String operation,
        String requestHash,
        Integer responseStatus,
        String responseBody,
        Instant createdAt) {
}

